contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Accept refunds/transfers from c during the test
    receive() external payable {}

    // Single public property test: amount must be provided as input to send Ether to c
    function run(uint amount) public payable {
        // we will only reason about the behavior when attempting to send exactly 10 ether
        // require the test caller provides the funds to this contract first
        require(address(this).balance >= amount);

        // record observable state before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // make the deciding call: call fallback by sending value and no data
        try c.call{value: amount}("") returns (bytes memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after the call
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint thisBal = address(this).balance;

        // General rule: if the call with the given amount did not revert and the amount equals 10 ether,
        // then pastBlockTime must have strictly increased, and either the contract paid out its entire balance
        // to this contract when block.number % 15 == 0 (so c balance decreased to 0 and this contract's balance increased accordingly),
        // or, if block.number % 15 != 0, the contract's balance must have increased exactly by 10 ether.
        assert(
            // only assert something meaningful when the call succeeded and the sent amount was exactly 10 ether
            (reverted || amount != 10 ether) || (
                // call succeeded and amount == 10 ether
                afterPast > beforePast && (
                    // either payout happened (c balance went to 0)
                    ((block.number % 15 == 0) && afterBal == 0) ||
                    // or no payout and c's balance increased by exactly 10 ether
                    ((block.number % 15 != 0) && afterBal == beforeBal + 10 ether)
                )
            )
        );
    }
 }

