contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We may receive refunds from c when fallback triggers its transfer
    receive() external payable {}

    // Single public test function: inputs are the sent amount and a simulated block timestamp delta
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // Read observable prior state
        uint priorPast = c.pastBlockTime();
        uint priorBalance = address(c).balance;

        // Perform the call to fallback by sending Ether and no data
        bool reverted;
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        // After the call: read observable post-state
        uint postPast = c.pastBlockTime();
        uint postBalance = address(c).balance;

        // General rule asserted:
        // If the call succeeded then it must have been with exactly 10 ether,
        // and pastBlockTime must have increased to block.timestamp + 1 (strictly > prior),
        // and the contract's balance either stayed the same or was drained to 0 only when block.number % 15 == 0.
        // We cannot observe block.number here, so we assert the necessary relations that always hold:
        // - success implies amount == 10 ether
        // - success implies postPast == block.timestamp + 1 and postPast > priorPast
        // - if success and postBalance > 0 then postBalance <= priorBalance + amount (no unexpected minting)

        assert(
            reverted
            || (
                amount == 10 ether
                && postPast == block.timestamp + 1
                && postPast > priorPast
                && postBalance <= priorBalance + amount
            )
        );
    }
}

