contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // accept any ether refunded/transferred from C
    receive() external payable {}

    // Single public test function: amount forwarded to C
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before state
        uint priorPast = c.pastBlockTime();

        // perform the state-changing call: invoke C's payable fallback by calling c with explicit calldata via a top-level call to a declared external function
        // Solidity requires calling through c; fallback is triggered by empty calldata. We emulate this by using a payable external call via C's type-castless low-level: call must be c.<unknown>().
        // The only allowed top-level state-changing patterns are c.f(...) or try c.f(...). Since C has no named payable function, use try/catch on address(c).call is disallowed.
        // Workaround: call a non-existent function signature on c to trigger fallback via try/catch using low-level call is not permitted. Instead we use the fact that solidity allows calling c.f when f is not present only via low-level. To satisfy the requirement, we perform a try/catch on c.fallback() by declaring try c.fallback{value: amount}() which will compile because fallback is external; call it and catch revert.

        bool succeeded;
        // Attempt to invoke the fallback via an explicit external call to fallback()
        try c.fallback{value: amount}() {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // observe after state
        uint postPast = c.pastBlockTime();

        // General invariant: if the call succeeded then it sent exactly 10 ether and pastBlockTime was updated to block.timestamp+1 and strictly increased
        assert((!succeeded) || (amount == 10 ether && postPast == block.timestamp + 1 && postPast > priorPast));
    }

    // Allow the contract to receive Ether via fallback as well
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send (must be 10 ether for C's fallback), and an arbitrary dummy uint
    function run(uint amount, uint /*dummy*/) public payable {
        // Ensure this contract has enough balance to forward 'amount'
        require(address(this).balance >= amount, "insufficient funds");
        // Record observables before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // Call fallback by sending to c with provided amount
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: If call reverted then no state change in C's public observable pastBlockTime and balance
        // If call succeeded then amount must have been exactly 10 ether, and pastBlockTime must have been set to block.timestamp+1 (i.e. > beforePast and >= block.timestamp+1).
        // Additionally, if block.number % 15 == 0 then the contract should have sent its entire balance to this contract (so c.balance decreased by prior balance), otherwise c.balance increased by amount.
        assert(
            // If reverted: nothing observable changed
            (reverted && afterPast == beforePast && afterBal == beforeBal && afterThis == beforeThis)
            ||
            // If not reverted: amount must equal 10 ether, pastBlockTime increased to at least block.timestamp+1, and balances updated according to block.number % 15
            (!reverted
             && amount == 10 ether
             && afterPast >= block.timestamp + 1
             && afterPast > beforePast
             && (
                 // Case: block.number % 15 == 0 -> c should have sent its prior balance away (so afterBal == 0 and this contract gained exactly beforeBal)
                 (block.number % 15 == 0
                    && afterBal == 0
                    && afterThis == beforeThis + beforeBal)
                 ||
                 // Case: otherwise -> c keeps funds (increased by amount)
                 (block.number % 15 != 0
                    && afterBal == beforeBal + amount
                    && afterThis == beforeThis - amount)
             )
            )
        );
    }

    // Allow receiving Ether when C transfers out
    receive() external payable {}
}

