    constructor(C _c) { c = _c; }

    // allow receiving refunds if C sends Ether back
    receive() external payable {}

    // Single public test function driving C's fallback; amount is forwarded to C.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Observe before-state
        uint beforePast = c.pastBlockTime();
        uint balBefore = address(c).balance;

        // Perform the state-changing call to C's fallback by calling c via its address.
        bool reverted;
        (reverted,) = address(c).call{value: amount}("");

        // Observe after-state
        uint afterPast = c.pastBlockTime();
        uint balAfter = address(c).balance;

        // General rule asserted once:
        // If the fallback call succeeded then amount == 10 ether and pastBlockTime == block.timestamp + 1.
        // If it reverted then either amount != 10 ether or prior pastBlockTime >= block.timestamp.
        assert((!reverted && amount == 10 ether && afterPast == block.timestamp + 1)
               || (reverted && (amount != 10 ether || beforePast >= block.timestamp)));
    }

    // Fallback to be able to receive plain transfers
    fallback() external payable {}
}

