contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Accept Ether when C sends funds back during fallback execution
    receive() external payable {}

    // Single public entry performing the property-based test
    function run(uint sendAmount) public payable {
        // we only model calls where the test contract supplies the Ether to send
        require(address(this).balance >= sendAmount, "insufficient balance to forward");

        // observe before-values
        uint before_past = c.pastBlockTime();
        uint before_balance = address(c).balance;
        uint before_block = block.number;
        uint before_ts = block.timestamp;

        bool reverted;
        // make the call to fallback by sending arbitrary calldata empty (fallback triggers)
        try c.f{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values (only via public surface)
        uint after_past = c.pastBlockTime();
        uint after_balance = address(c).balance;

        // General rule asserted:
        // If the call reverted, nothing further is assumed here.
        // If it did not revert then:
        //  - pastBlockTime must have been updated to at least block.timestamp+1 (i.e., > previous pastBlockTime and >= current timestamp+1)
        //  - If block.number % 15 == 0 then contract forwarded all its balance to caller (so its balance decreased by exactly before_balance + sendAmount)
        //    (Since transfer sends entire balance in that branch, after_balance should be 0)
        //  - Otherwise contract kept the sent funds (balance increased by sendAmount)
        // We express these as a single assert combining the cases.
        assert(
            reverted || (
                // pastBlockTime must be at least current timestamp + 1
                after_past >= before_ts + 1 &&
                // Balance behavior depends on block.number % 15
                ((before_block % 15 == 0 && after_balance == 0) || (before_block % 15 != 0 && after_balance == before_balance + sendAmount))
            )
        );
    }
}

