contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept two inputs: the amount of wei to send and an external timestamp bump indicator
    // (the latter is not used directly because we cannot change block.timestamp here).
    // The function is payable so the f{value:...} call can forward Ether from this contract.
    function run(uint amount) public payable {
        require(amount >= 0);
        // Ensure this contract has enough balance to forward the requested amount to c
        require(address(this).balance >= amount);

        // Read the observable pre-state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Make the call to fallback with the chosen amount
        bool reverted;
        // The fallback in C requires msg.value == 10 ether to proceed
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint selfBal = address(this).balance;

        // General rule: If the call did not revert and we sent exactly 10 ether, then either
        // (A) pastBlockTime strictly increased (the contract updated it to block.timestamp+1),
        // or (B) when block.number % 15 == 0 the contract forwarded its entire balance to this contract
        // (observable as c balance decreasing and this contract balance increasing by that amount).
        // We express this without referring to block.number directly by observing balances:
        // If not reverted and amount == 10 ether then either afterPast > beforePast or afterBal == 0.
        assert(reverted || amount != 10 ether || (afterPast > beforePast) || (afterBal == 0));
    }

    // Allow the contract to receive Ether when C transfers out its balance
    receive() external payable {}
}

