contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We need to receive Ether when C.transfer sends us funds.
    receive() external payable {}

    // single public function with parameters: amount to send and a flag to simulate block.number mod 15 by calling at arbitrary times
    function run(uint amount) public payable {
        // we require the test caller supplied the correct Ether to forward to c
        require(msg.value == amount);
        // Only meaningful inputs are amount == 10 ether; other amounts should cause fallback to revert.

        // Observe pre-state
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // Make the call to C's fallback by sending Ether to it. Must have balance to do so.
        require(address(this).balance >= amount);
        bool reverted;
        // perform call and catch revert
        try c.call{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // If call reverted then state must be unchanged (pastBlockTime and balance unchanged).
        // If call did not revert and amount == 10 ether then: afterPast == block.timestamp + 1 AND afterPast > beforePast.
        // Also if the contract forwarded all funds (i.e., block.number % 15 == 0) then its balance becomes 0, else its balance increases by amount.

        // We cannot reference block.number%15 deterministically here, so express the transfer behavior as: if balance decreased then it must be zero; otherwise balance == beforeBalance + amount.
        assert(
            (
                reverted && afterPast == beforePast && afterBalance == beforeBalance
            ) || (
                !reverted && amount == 10 ether && afterPast == block.timestamp + 1 && afterPast > beforePast &&
                (
                    (afterBalance < beforeBalance + amount && afterBalance == 0) || (afterBalance == beforeBalance + amount)
                )
            )
        );
    }

    // low-level call helper to invoke fallback of C
    fallback() external payable {}
}
